mapper.select:
SELECT id, summary, application_id, chat_user_id, chat_user_type, asker, meta, star_num, trample_num, chat_record_count, mark_sum, is_deleted, ip_address, source, create_time, update_time FROM application_chat
application_id = #{appId}
AND summary LIKE '%' || #{query.summary} || '%'
AND asker ->> 'username' LIKE '%' || #{query.username} || '%'
AND create_time >= CAST(#{query.startTime} AS TIMESTAMP)
AND create_time < CAST(#{query.endTime} AS TIMESTAMP) + INTERVAL '1 day'
AND star_num >= #{query.minStar}
AND trample_num >= #{query.minTrample}
ORDER BY create_time DESC

SELECT SUM(chat.star_num) AS star_num, SUM (chat.trample_num) AS trample_num, SUM(chat.chat_record_count) as chat_record_count, SUM(chat_record.tokens_num) as tokens_num, COUNT(DISTINCT chat.chat_user_id) customer_num, chat.create_time :: DATE as "day" FROM application_chat chat LEFT JOIN ( select r.chat_id, ( SUM (r.message_tokens)+ SUM (r.answer_tokens)) as tokens_num FROM application_chat_record r INNER JOIN application_chat c ON r.chat_id = c.id
c.APPLICATION_ID = #{appId}
and c.CREATE_TIME >= CAST(#{query.startTime} AS TIMESTAMP)
and c.CREATE_TIME < CAST(#{query.endTime} AS TIMESTAMP) + INTERVAL '1 day'
GROUP BY r.chat_id ) chat_record ON chat."id" = chat_record.chat_id
APPLICATION_ID = #{appId}
and CREATE_TIME >= CAST(#{query.startTime} AS TIMESTAMP)
and CREATE_TIME < CAST(#{query.endTime} AS TIMESTAMP) + INTERVAL '1 day'
GROUP BY "day";

SELECT SUM(chat_record.tokens_num) as tokenUsage, "user".nickname as userName FROM application_chat chat LEFT JOIN ( select r.chat_id, ( SUM (r.message_tokens)+ SUM (r.answer_tokens)) as tokens_num FROM application_chat_record r INNER JOIN application_chat c ON r.chat_id = c.id
c.APPLICATION_ID = #{appId}
and c.CREATE_TIME >= CAST(#{query.startTime} AS TIMESTAMP)
and c.CREATE_TIME < CAST(#{query.endTime} AS TIMESTAMP) + INTERVAL '1 day'
GROUP BY r.chat_id ) chat_record ON chat."id" = chat_record.chat_id INNER JOIN "user" ON chat.chat_user_id = "user"."id"
APPLICATION_ID = #{appId}
and chat.CREATE_TIME >= CAST(#{query.startTime} AS TIMESTAMP)
and chat.CREATE_TIME < CAST(#{query.endTime} AS TIMESTAMP) + INTERVAL '1 day'
GROUP BY "user"."id";

SELECT SUM(chat.chat_record_count) as chat_record_count, "user".nickname as userName FROM application_chat chat INNER JOIN "user" ON chat.chat_user_id = "user"."id"
APPLICATION_ID = #{appId}
and chat.CREATE_TIME >= CAST(#{query.startTime} AS TIMESTAMP)
and chat.CREATE_TIME < CAST(#{query.endTime} AS TIMESTAMP) + INTERVAL '1 day'
GROUP BY "user"."id";

SELECT record.chat_id,chat.summary,record.vote_status,record.problem_text,record.answer_text, record.cost,record."index", record.run_time, record.create_time FROM application_chat chat LEFT JOIN application_chat_record record ON chat.id=record.chat_id WHERE chat.id IN
#{id}
ORDER BY chat.id,record.create_time
